#include <torch/extension.h>

torch::Tensor elu_forward_cuda(torch::Tensor x, double alpha);

PYBIND11_MODULE(TORCH_EXTENSION_NAME, m) {
    m.def("elu_forward", &elu_forward_cuda, "ELU forward (CUDA)");
}
# <<<END_IMPROVE>>>
