#include <torch/extension.h>
#include <ATen/cuda/CUDAContext.h>
#include <cuda.h>
#include <cuda_runtime.h>

__device__ __forceinline__ float elu_scalar(float v, float alpha) {
    return v >= 0.0f ? v : alpha * (__expf(v) - 1.0f);
}

__global__ void elu_vec4_kernel(const float4* __restrict__ in, float4* __restrict__ out,
                                 int64_t vecN, float alpha) {
    int64_t idx = (int64_t)blockIdx.x * blockDim.x + threadIdx.x;
    int64_t stride = (int64_t)gridDim.x * blockDim.x;
    for (int64_t i = idx; i < vecN; i += stride) {
        float4 v = in[i];
        v.x = elu_scalar(v.x, alpha);
        v.y = elu_scalar(v.y, alpha);
        v.z = elu_scalar(v.z, alpha);
        v.w = elu_scalar(v.w, alpha);
        out[i] = v;
    }
}

__global__ void elu_scalar_kernel(const float* __restrict__ in, float* __restrict__ out,
                                   int64_t offset, int64_t n, float alpha) {
    int64_t idx = (int64_t)blockIdx.x * blockDim.x + threadIdx.x;
    int64_t stride = (int64_t)gridDim.x * blockDim.x;
    for (int64_t i = idx; i < n; i += stride) {
        out[offset + i] = elu_scalar(in[offset + i], alpha);
    }
