    TORCH_CHECK(x.is_cuda(), "x must be a CUDA tensor");
    TORCH_CHECK(x.scalar_type() == at::kFloat, "x must be float32");
    TORCH_CHECK(x.is_contiguous(), "x must be contiguous");

    auto out = torch::empty_like(x);
    int64_t numel = x.numel();
    if (numel == 0) return out;

    float alpha_f = (float)alpha;
    const float* in_ptr = x.data_ptr<float>();
    float* out_ptr = out.data_ptr<float>();

    cudaStream_t stream = at::cuda::getDefaultCUDAStream();

    int64_t vecN = numel / 4;
    int64_t tail = numel % 4;

    const int threads = 256;

    if (vecN > 0) {
        int blocks = (int)min((vecN + threads - 1) / threads, (int64_t)4096);
        elu_vec4_kernel<<<blocks, threads, 0, stream>>>(
            reinterpret_cast<const float4*>(in_ptr),
            reinterpret_cast<float4*>(out_ptr),
            vecN, alpha_f);
    }

    if (tail > 0) {
        int64_t offset = vecN * 4;
        int blocks = (int)min((tail + threads - 1) / threads, (int64_t)32);
        elu_scalar_kernel<<<blocks, threads, 0, stream>>>(
            in_ptr, out_ptr, offset, tail, alpha_f);
    }

    return out;
}
